                     <div className="flex items-center gap-1 text-warning text-xs font-bold uppercase tracking-wider">
                         <Icon name="flag" className="text-sm" fill />
                         Flagged
                     </div>
                 )}
              </div>
              <h2 className="text-[#0e121b] dark:text-white text-2xl lg:text-3xl font-bold leading-tight mb-8">
                {currentQuestion.text}
              </h2>
              <div className="flex flex-col gap-4">
                {currentQuestion.options.map((opt) => {
                  const isSelected = answers[currentQuestion.id] === opt.id;
                  return (
                    <label 
                      key={opt.id} 
                      className={`group flex items-center gap-4 rounded-xl border-2 p-5 cursor-pointer transition-all ${isSelected ? 'border-primary bg-primary/5 dark:bg-primary/10' : 'border-[#d0d7e7] dark:border-[#2d364d] hover:border-primary/50 bg-white dark:bg-[#1a2133]'}`}
                    >
                      <input 
                        type="radio" 
                        name={`question-${currentQuestion.id}`} 
                        className="h-6 w-6 border-2 border-[#d0d7e7] dark:border-[#2d364d] bg-transparent text-transparent checked:border-primary checked:text-primary focus:ring-0 focus:ring-offset-0" 
                        checked={isSelected}
                        onChange={() => handleOptionSelect(opt.id)}
                      />
                      <div className="flex grow flex-col">
                        <p className={`text-lg font-medium transition-colors ${isSelected ? 'text-primary font-bold' : 'text-[#0e121b] dark:text-white'}`}>{opt.text}</p>
                        {opt.subText && <p className={`text-sm transition-colors ${isSelected ? 'text-[#4e6797] dark:text-primary/70' : 'text-[#4e6797] dark:text-[#94a3b8]'}`}>{opt.subText}</p>}
                      </div>
                    </label>
                  );
                })}
              </div>
            </div>
            <div className="border-t border-[#e7ebf3] dark:border-[#2d364d] p-4 lg:p-6 bg-gray-50 dark:bg-[#1e273a] flex items-center justify-between transition-colors">
              <button 
                onClick={() => setCurrentQuestionIndex(prev => Math.max(0, prev - 1))}
                disabled={isFirstQuestion}
                className={`flex items-center gap-2 px-6 py-3 border rounded-lg text-sm font-bold transition-all shadow-sm ${isFirstQuestion ? 'bg-gray-100 dark:bg-gray-800 text-gray-400 border-transparent cursor-not-allowed' : 'bg-white dark:bg-[#2d364d] border-[#d0d7e7] dark:border-[#404b69] text-[#0e121b] dark:text-white hover:bg-gray-100 dark:hover:bg-[#3d4863]'}`}
              >
                <Icon name="arrow_back" /> Previous
              </button>

              <button 
                onClick={toggleFlag}
                className={`flex items-center gap-2 px-6 py-3 border rounded-lg text-sm font-bold transition-all shadow-sm ${flagged.has(currentQuestion.id) ? 'bg-amber-50 dark:bg-amber-900/20 text-amber-600 border-amber-200 dark:border-amber-800' : 'bg-white dark:bg-[#2d364d] border-[#d0d7e7] dark:border-[#404b69] text-[#0e121b] dark:text-white hover:bg-gray-100 dark:hover:bg-[#3d4863]'}`}
              >
                <Icon name="flag" className={flagged.has(currentQuestion.id) ? 'fill-1' : ''} /> 
                {flagged.has(currentQuestion.id) ? 'Unflag' : 'Flag for Review'}
              </button>

              <button 
                onClick={() => setCurrentQuestionIndex(prev => Math.min(totalQuestions - 1, prev + 1))}
                disabled={isLastQuestion}
                className={`flex items-center gap-2 px-8 py-3 rounded-lg text-sm font-bold transition-all shadow-lg ${isLastQuestion ? 'bg-gray-300 dark:bg-gray-700 text-gray-500 cursor-not-allowed' : 'bg-primary text-white hover:bg-blue-700 shadow-primary/20'}`}
              >
                Next Question <Icon name="arrow_forward" />
              </button>
            </div>
          </div>
          <div className="flex items-start gap-4 p-4 rounded-xl bg-primary/5 border border-primary/20 text-[#4e6797] dark:text-blue-300">
            <Icon name="info" className="text-primary" />
            <p className="text-sm">Review your answer carefully. Shuffled options might appear differently than in your study materials.</p>
          </div>
        </div>

        <aside className="w-full lg:w-80 shrink-0">
          <div className="bg-white dark:bg-[#1a2133] rounded-xl border border-[#e7ebf3] dark:border-[#2d364d] shadow-sm sticky top-[100px] transition-colors">
            <div className="p-5 border-b border-[#e7ebf3] dark:border-[#2d364d]">
              <h3 className="text-sm font-bold uppercase tracking-widest text-[#4e6797] dark:text-[#94a3b8]">Question Map</h3>
            </div>
            <div className="p-5">
              <div className="grid grid-cols-2 gap-3 mb-6">
                <div className="flex items-center gap-2"><div className="size-3 rounded bg-primary"></div><span className="text-[10px] font-bold uppercase text-[#4e6797] dark:text-[#94a3b8]">Answered</span></div>
                <div className="flex items-center gap-2"><div className="size-3 rounded bg-warning"></div><span className="text-[10px] font-bold uppercase text-[#4e6797] dark:text-[#94a3b8]">Flagged</span></div>
                <div className="flex items-center gap-2"><div className="size-3 rounded border-2 border-primary"></div><span className="text-[10px] font-bold uppercase text-[#4e6797] dark:text-[#94a3b8]">Current</span></div>
                <div className="flex items-center gap-2"><div className="size-3 rounded bg-[#d0d7e7] dark:bg-[#2d364d]"></div><span className="text-[10px] font-bold uppercase text-[#4e6797] dark:text-[#94a3b8]">Remaining</span></div>
              </div>
              <div className="grid grid-cols-5 gap-2">
                {QUESTIONS.map((q, i) => {
                  const isAnswered = answers[q.id] !== undefined;
                  const isFlagged = flagged.has(q.id);
                  const isCurrent = currentQuestionIndex === i;

                  let styles = "bg-[#d0d7e7] dark:bg-[#2d364d] text-[#4e6797] dark:text-[#94a3b8] hover:opacity-80";

                  if (isCurrent) {
                      styles = "border-2 border-primary text-primary bg-white dark:bg-[#1a2133]";
                  } else if (isFlagged) {
                      styles = "bg-warning text-white";
                  } else if (isAnswered) {
                      styles = "bg-primary text-white";
                  }

                  return (
                    <button 
                      key={q.id} 
                      onClick={() => setCurrentQuestionIndex(i)}
                      className={`aspect-square flex items-center justify-center rounded-lg text-xs font-bold transition-all ${styles}`}
                    >
                      {i + 1}
                    </button>
                  );
                })}
              </div>
              <div className="mt-8">
                <button className="w-full py-3 bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 border border-red-200 dark:border-red-900/50 rounded-lg text-sm font-bold flex items-center justify-center gap-2 hover:bg-red-100 dark:hover:bg-red-900/30 transition-colors">
                  <Icon name="logout" /> Finish & Submit
                </button>
                <p className="text-[10px] text-center text-[#4e6797] dark:text-[#94a3b8] mt-3">All progress is automatically saved</p>
              </div>
            </div>
          </div>
        </aside>
      </main>
    </div>
  );
};

import React, { useState } from 'react';
import { Login } from './pages/Login';
import { UserRole, View } from './types';
import { TeacherLayout, AdminLayout, ParentLayout } from './components/Layouts';
import { TeacherDashboard } from './pages/teacher/TeacherDashboard';
import { TeacherQuizConfig } from './pages/teacher/TeacherQuizConfig';
import { TeacherQuizShare } from './pages/teacher/TeacherQuizShare';
import { TeacherQuizResults } from './pages/teacher/TeacherQuizResults';
import { TeacherReportEntry } from './pages/teacher/TeacherReportEntry';
import { TeacherAssignments } from './pages/teacher/TeacherAssignments';
import { TeacherAttendance } from './pages/teacher/TeacherAttendance';
import { AdminDashboard } from './pages/admin/AdminDashboard';
import { AdminRegistration } from './pages/admin/AdminRegistration';
import { AdminFees } from './pages/admin/AdminFees';
import { AdminCalendar } from './pages/admin/AdminCalendar';
import { AdminApprovals } from './pages/admin/AdminApprovals';
import { AdminFeeConfig } from './pages/admin/AdminFeeConfig';
import { ParentDashboard } from './pages/parent/ParentDashboard';
import { ParentFees } from './pages/parent/ParentFees';
import { ParentAssignments } from './pages/parent/ParentAssignments';
import { ParentReports } from './pages/parent/ParentReports';
import { ParentReportDetail } from './pages/parent/ParentReportDetail';
import { StudentQuiz } from './pages/student/StudentQuiz';

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole | null>(null);
  const [currentView, setCurrentView] = useState<View>(View.LOGIN);

  const handleLogin = (selectedRole: UserRole) => {
    setRole(selectedRole);
    switch (selectedRole) {
      case UserRole.TEACHER:
        setCurrentView(View.TEACHER_DASHBOARD);
        break;
      case UserRole.ADMIN:
        setCurrentView(View.ADMIN_DASHBOARD);
        break;
      case UserRole.PARENT:
        setCurrentView(View.PARENT_DASHBOARD);
        break;
      case UserRole.STUDENT:
        setCurrentView(View.STUDENT_QUIZ);
        break;
      default:
        setCurrentView(View.TEACHER_DASHBOARD);
    }
  };

  const handleNavigation = (view: View) => {
    setCurrentView(view);
  };

  if (!role || currentView === View.LOGIN) {
    return <Login onLogin={handleLogin} />;
  }

  if (role === UserRole.TEACHER) {
    return (
      <TeacherLayout onNavigate={handleNavigation} currentView={currentView} role={role}>
        {currentView === View.TEACHER_DASHBOARD && <TeacherDashboard />}
        {currentView === View.TEACHER_QUIZ_CONFIG && <TeacherQuizConfig onNavigate={handleNavigation} />}
        {currentView === View.TEACHER_QUIZ_SHARE && <TeacherQuizShare onNavigate={handleNavigation} />}
        {currentView === View.TEACHER_QUIZ_RESULTS && <TeacherQuizResults onNavigate={handleNavigation} />}
        {currentView === View.TEACHER_REPORT_ENTRY && <TeacherReportEntry />}
        {currentView === View.TEACHER_ASSIGNMENTS && <TeacherAssignments />}
        {currentView === View.TEACHER_ATTENDANCE && <TeacherAttendance />}
      </TeacherLayout>
    );
  }

  if (role === UserRole.ADMIN) {
    return (
      <AdminLayout onNavigate={handleNavigation} currentView={currentView} role={role}>
        {currentView === View.ADMIN_DASHBOARD && <AdminDashboard />}
        {currentView === View.ADMIN_REGISTRATION && <AdminRegistration />}
        {currentView === View.ADMIN_FEES && <AdminFees />}
        {currentView === View.ADMIN_CALENDAR && <AdminCalendar />}
        {currentView === View.ADMIN_APPROVALS && <AdminApprovals />}
        {/* Reuse AdminFees or redirect to config if needed, usually linked from Fees page */}
        {currentView === View.ADMIN_FEE_CONFIG && <AdminFeeConfig />}
      </AdminLayout>
    );
  }

  if (role === UserRole.PARENT) {
    return (
      <ParentLayout onNavigate={handleNavigation} currentView={currentView} role={role}>
        {currentView === View.PARENT_DASHBOARD && <ParentDashboard />}
        {currentView === View.PARENT_FEES && <ParentFees />}
        {currentView === View.PARENT_ASSIGNMENTS && <ParentAssignments />}
        {currentView === View.PARENT_REPORTS && <ParentReports onNavigate={handleNavigation} />}
        {currentView === View.PARENT_REPORT_DETAIL && <ParentReportDetail onNavigate={handleNavigation} />}
      </ParentLayout>
    );
  }

  // Student view is standalone typically
  if (role === UserRole.STUDENT || currentView === View.STUDENT_QUIZ) {
    return <StudentQuiz />;
  }

  return <div>Unknown Role</div>;
};

export default App;

