                </div>
            </div>

            <div className="bg-blue-50 dark:bg-blue-900/10 border border-blue-100 dark:border-blue-900/30 rounded-xl p-4 flex gap-3 text-blue-700 dark:text-blue-300">
                <Icon name="info" className="shrink-0" />
                <p className="text-xs leading-relaxed">Review your answer carefully. Shuffled options might appear differently than in your study materials.</p>
            </div>
        </div>

        {/* Right Column: Sidebar */}
        <div className="lg:col-span-3">
            <div className="bg-white dark:bg-[#1e293b] rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 p-6 sticky top-24">
                <h3 className="text-xs font-bold uppercase tracking-wider text-slate-500 mb-6">Question Map</h3>

                <div className="grid grid-cols-2 gap-y-3 gap-x-2 mb-8">
                    <div className="flex items-center gap-2">
                        <div className="size-3 rounded-full bg-primary"></div>
                        <span className="text-[10px] font-bold uppercase text-slate-500">Answered</span>
                    </div>
                    <div className="flex items-center gap-2">
                        <div className="size-3 rounded-full bg-amber-400"></div>
                        <span className="text-[10px] font-bold uppercase text-slate-500">Flagged</span>
                    </div>
                    <div className="flex items-center gap-2">
                        <div className="size-3 rounded-full border-2 border-primary bg-white dark:bg-transparent"></div>
                        <span className="text-[10px] font-bold uppercase text-slate-500">Current</span>
                    </div>
                    <div className="flex items-center gap-2">
                        <div className="size-3 rounded-full bg-slate-200 dark:bg-slate-700"></div>
                        <span className="text-[10px] font-bold uppercase text-slate-500">Remaining</span>
                    </div>
                </div>

                <div className="grid grid-cols-5 gap-2 mb-8">
                    {QUESTIONS.map((q, i) => {
                        const isAnswered = answers[q.id] !== undefined;
                        const isFlagged = flagged.has(q.id);
                        const isCurrent = currentQuestionIndex === i;

                        let classes = "bg-slate-100 text-slate-500 dark:bg-slate-700/50 dark:text-slate-400"; // default

                        if (isCurrent) {
                            classes = "border-2 border-primary text-primary bg-white dark:bg-[#1e293b]";
                        } else if (isFlagged) {
                            classes = "bg-amber-400 text-white shadow-sm shadow-amber-200";
                        } else if (isAnswered) {
                            classes = "bg-primary text-white shadow-sm shadow-blue-200";
                        }

                        return (
                            <button 
                                key={q.id}
                                onClick={() => setCurrentQuestionIndex(i)}
                                className={`aspect-square rounded-lg flex items-center justify-center text-xs font-bold transition-all hover:scale-105 ${classes}`}
                            >
                                {i + 1}
                            </button>
                        )
                    })}
                </div>

                <button className="w-full py-3 rounded-xl border border-red-200 dark:border-red-900/50 bg-red-50 dark:bg-red-900/10 text-red-600 dark:text-red-400 font-bold text-sm flex items-center justify-center gap-2 hover:bg-red-100 dark:hover:bg-red-900/20 transition-colors group">
                    <Icon name="logout" className="text-lg transition-transform group-hover:translate-x-1" /> Finish & Submit
                </button>
                <p className="text-[10px] text-center text-slate-400 mt-4">All progress is automatically saved</p>
            </div>
        </div>

      </main>

      <footer className="p-6 text-center text-xs text-slate-400 border-t border-slate-200 dark:border-slate-800 bg-white dark:bg-[#1e293b]">
          <div className="flex justify-between items-center max-w-7xl mx-auto">
              <span>&copy; 2023 GlobalFire School Management System. All rights reserved.</span>
              <div className="flex items-center gap-4">
                  <span className="flex items-center gap-1"><Icon name="lock" className="text-xs" /> Secure Exam Environment</span>
                  <span className="flex items-center gap-1"><Icon name="wifi" className="text-xs" /> Online</span>
              </div>
          </div>
      </footer>
    </div>
  );
};

