export const StudentQuiz: React.FC = () => {
  const [studentId, setStudentId] = useState<string | null>(null);
  const [tempId, setTempId] = useState('');
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [answers, setAnswers] = useState<Record<number, string>>({});
  const [flagged, setFlagged] = useState<Set<number>>(new Set());
  const [timeLeft, setTimeLeft] = useState(14 * 60 + 59); // 14:59 start
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [score, setScore] = useState(0);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if(tempId.trim()) setStudentId(tempId);
  }

  const currentQuestion = QUESTIONS[currentQuestionIndex];
  const totalQuestions = QUESTIONS.length;
  const isLastQuestion = currentQuestionIndex === totalQuestions - 1;
  const isFirstQuestion = currentQuestionIndex === 0;

  useEffect(() => {
    if(!studentId || isSubmitted) return;
    const timer = setInterval(() => {
      setTimeLeft((prev) => {
        if (prev <= 0) {
            clearInterval(timer);
            return 0;
        }
        return prev - 1;
      });
    }, 1000);
    return () => clearInterval(timer);
  }, [studentId, isSubmitted]);

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s.toString().padStart(2, '0')}`;
  };

  const handleOptionSelect = (optionId: string) => {
    setAnswers(prev => ({
      ...prev,
      [currentQuestion.id]: optionId
    }));
  };

  const toggleFlag = () => {
    const newFlagged = new Set(flagged);
    if (newFlagged.has(currentQuestion.id)) {
      newFlagged.delete(currentQuestion.id);
    } else {
      newFlagged.add(currentQuestion.id);
    }
    setFlagged(newFlagged);
  };

  const handleSubmit = () => {
    let calculatedScore = 0;
    QUESTIONS.forEach(q => {
      if (answers[q.id] === q.correctAnswer) {
        calculatedScore += q.points;
      }
    });
    setScore(calculatedScore);
    setIsSubmitted(true);
  };

  const progressPercentage = Math.round((Object.keys(answers).length / totalQuestions) * 100);

  if (!studentId) {
      return (
          <div className="min-h-screen bg-background-light dark:bg-background-dark flex items-center justify-center p-6 font-display">
              <div className="bg-white dark:bg-slate-900 rounded-xl shadow-xl max-w-md w-full p-8 border border-slate-200 dark:border-slate-800">
                  <div className="text-center mb-8">
                      <div className="size-16 bg-primary/10 rounded-full flex items-center justify-center mx-auto mb-4 text-primary">
                          <Icon name="badge" className="text-3xl" />
                      </div>
                      <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Student Quiz Portal</h1>
                      <p className="text-slate-500 mt-2 text-sm">Please enter your Student ID to begin the assessment.</p>
                  </div>
                  <form onSubmit={handleLogin} className="space-y-4">
                      <div>
                          <label className="block text-xs font-bold uppercase text-slate-500 mb-2">Student ID</label>
                          <input 
                            type="text" 
                            value={tempId}
                            onChange={(e) => setTempId(e.target.value)}
                            className="w-full p-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg font-mono text-center text-lg tracking-wider font-bold focus:ring-primary focus:border-primary uppercase"
                            placeholder="e.g. STU-2024-001"
                            required
                          />
                      </div>
                      <button type="submit" className="w-full py-3 bg-primary text-white font-bold rounded-lg hover:bg-primary/90 transition-colors shadow-lg shadow-primary/20 flex items-center justify-center gap-2">
                          Start Assessment <Icon name="arrow_forward" />
                      </button>
                  </form>
                  <div className="mt-6 pt-6 border-t border-slate-100 dark:border-slate-800 text-center">
                       <p className="text-xs text-slate-400">Quiz: Advanced Biology - Midterm</p>
                  </div>
              </div>
          </div>
      )
  }

  if (isSubmitted) {
    const totalPoints = QUESTIONS.reduce((acc, q) => acc + q.points, 0);
    const scorePercentage = Math.round((score / totalPoints) * 100);

    let grade = 'F';
    let gradeColor = 'text-red-500 bg-red-50 dark:bg-red-900/20';
    if (scorePercentage >= 90) { grade = 'A'; gradeColor = 'text-green-600 bg-green-50 dark:bg-green-900/20'; }
    else if (scorePercentage >= 80) { grade = 'B'; gradeColor = 'text-blue-600 bg-blue-50 dark:bg-blue-900/20'; }
    else if (scorePercentage >= 70) { grade = 'C'; gradeColor = 'text-yellow-600 bg-yellow-50 dark:bg-yellow-900/20'; }
    else if (scorePercentage >= 60) { grade = 'D'; gradeColor = 'text-orange-600 bg-orange-50 dark:bg-orange-900/20'; }

    return (
      <div className="min-h-screen bg-background-light dark:bg-background-dark font-display flex flex-col items-center p-6">
        <div className="max-w-4xl w-full space-y-8">
          {/* Header */}
          <div className="text-center">
             <div className="inline-flex items-center gap-2 bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-400 px-4 py-1.5 rounded-full text-sm font-bold mb-4">
                <Icon name="check_circle" className="text-lg" /> Submission Successful
             </div>
             <h1 className="text-3xl font-bold text-slate-900 dark:text-white">Results Summary</h1>
             <p className="text-slate-500 mt-2">Advanced Biology - Midterm • Exam ID: BIO-402-2024</p>
          </div>

          {/* Score Card */}
          <div className="bg-white dark:bg-[#1e293b] rounded-2xl shadow-lg border border-slate-200 dark:border-slate-700 p-8 grid grid-cols-1 md:grid-cols-3 gap-8 items-center">
              <div className="text-center md:text-left">
                  <p className="text-sm font-bold uppercase text-slate-500 mb-1">Total Score</p>
                  <p className="text-5xl font-black text-slate-900 dark:text-white">{score} <span className="text-2xl text-slate-400 font-bold">/ {totalPoints}</span></p>
              </div>

              <div className="flex flex-col items-center justify-center">
                  <div className={`size-24 rounded-full flex items-center justify-center text-4xl font-black mb-2 ${gradeColor}`}>
                      {grade}
                  </div>
                  <p className="text-sm font-bold text-slate-500">Final Grade</p>
              </div>

              <div className="space-y-4">
                  <div className="flex justify-between items-center p-3 rounded-lg bg-slate-50 dark:bg-slate-800">
                      <span className="text-sm font-bold text-slate-600 dark:text-slate-300">Accuracy</span>
                      <span className="font-bold text-slate-900 dark:text-white">{scorePercentage}%</span>
                  </div>
                  <div className="flex justify-between items-center p-3 rounded-lg bg-slate-50 dark:bg-slate-800">
                      <span className="text-sm font-bold text-slate-600 dark:text-slate-300">Time Taken</span>
                      <span className="font-bold text-slate-900 dark:text-white">12m 45s</span>
                  </div>
              </div>
          </div>

          {/* Question Review */}
          <div className="space-y-6">
              <h2 className="text-xl font-bold text-slate-900 dark:text-white px-2">Detailed Review</h2>
              {QUESTIONS.map((q, index) => {
                  const userAnswer = answers[q.id];
                  const isCorrect = userAnswer === q.correctAnswer;
                  const isSkipped = userAnswer === undefined;

                  return (
                      <div key={q.id} className={`bg-white dark:bg-[#1e293b] rounded-xl border p-6 ${isCorrect ? 'border-green-200 dark:border-green-900/30' : isSkipped ? 'border-slate-200 dark:border-slate-700' : 'border-red-200 dark:border-red-900/30'}`}>
                          <div className="flex items-start gap-4">
                              <div className={`size-8 rounded-full flex items-center justify-center shrink-0 font-bold text-white text-sm ${isCorrect ? 'bg-green-500' : isSkipped ? 'bg-slate-400' : 'bg-red-500'}`}>
                                  {isCorrect ? <Icon name="check" /> : isSkipped ? <Icon name="remove" /> : <Icon name="close" />}
                              </div>
                              <div className="flex-1">
                                  <div className="flex justify-between items-start mb-2">
                                      <h3 className="font-bold text-slate-900 dark:text-white text-lg">{index + 1}. {q.text}</h3>
                                      <span className="text-xs font-bold bg-slate-100 dark:bg-slate-800 px-2 py-1 rounded text-slate-500">{q.points} pts</span>
                                  </div>

                                  <div className="space-y-2 mt-4">
                                      {q.options.map(opt => {
                                          const isSelected = userAnswer === opt.id;
                                          const isTheCorrectAnswer = q.correctAnswer === opt.id;

                                          let optionClass = "border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 opacity-70";
                                          let icon = null;

                                          if (isTheCorrectAnswer) {
                                              optionClass = "border-green-500 bg-green-50 dark:bg-green-900/20 text-green-700 dark:text-green-300 font-bold ring-1 ring-green-500";
                                              icon = <Icon name="check_circle" className="text-green-500" />;
                                          } else if (isSelected && !isCorrect) {
                                              optionClass = "border-red-500 bg-red-50 dark:bg-red-900/20 text-red-700 dark:text-red-300 font-bold";
                                              icon = <Icon name="cancel" className="text-red-500" />;
                                          }

                                          return (
                                              <div key={opt.id} className={`flex items-center justify-between p-3 rounded-lg border text-sm ${optionClass}`}>
                                                  <span>{opt.text}</span>
                                                  {icon}
                                              </div>
                                          )
                                      })}
                                  </div>
                              </div>
                          </div>
                      </div>
                  )
              })}
          </div>

          <div className="flex justify-center gap-4 py-8">
              <button 
                onClick={() => window.print()} 
                className="px-6 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg font-bold text-slate-700 dark:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-700 flex items-center gap-2"
              >
                  <Icon name="print" /> Print Results
              </button>
              <button 
                onClick={() => {
                    setIsSubmitted(false);
                    setStudentId(null);
                    setAnswers({});
                    setScore(0);
                    setCurrentQuestionIndex(0);
                }}
                className="px-6 py-3 bg-primary text-white rounded-lg font-bold hover:bg-primary/90 shadow-lg shadow-primary/20 flex items-center gap-2"
              >
                  <Icon name="logout" /> Exit Exam
              </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-[#f8fafc] dark:bg-background-dark font-display text-slate-900 dark:text-white min-h-screen flex flex-col">
      {/* Navbar */}
      <header className="sticky top-0 z-50 bg-white dark:bg-[#1e293b] border-b border-slate-200 dark:border-slate-800 h-16 px-4 lg:px-8 flex items-center justify-between shadow-sm">
        <div className="flex items-center gap-3">
            <div className="bg-primary text-white p-1.5 rounded-lg">
                <Icon name="school" className="text-xl" />
            </div>
            <div>
                <h1 className="text-sm lg:text-base font-bold text-slate-900 dark:text-white leading-tight">Advanced Biology - Midterm</h1>
                <p className="text-[10px] text-slate-500 dark:text-slate-400 font-mono">Exam ID: BIO-402-2024</p>
            </div>
        </div>

        <div className="hidden md:flex flex-col w-64 gap-1">
             <div className="flex justify-between items-end">
                 <span className="text-[10px] font-bold uppercase text-slate-400">Progress</span>
                 <span className="text-xs font-bold text-slate-700 dark:text-slate-200">{progressPercentage}%</span>
             </div>
             <div className="h-1.5 w-full bg-slate-100 dark:bg-slate-700 rounded-full overflow-hidden">
                 <div className="h-full bg-primary transition-all duration-300 rounded-full" style={{ width: `${progressPercentage}%` }}></div>
             </div>
        </div>

        <div className="flex items-center gap-3">
            <div className={`flex items-center gap-2 px-3 py-1.5 rounded-lg border ${timeLeft < 300 ? 'bg-red-50 text-red-600 border-red-200' : 'bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 border-red-100 dark:border-red-900/30'}`}>
                <Icon name="timer" className="text-lg" />
                <span className="font-mono font-bold text-sm">{formatTime(timeLeft)}</span>
            </div>
        </div>
      </header>

      <main className="flex-1 max-w-7xl mx-auto w-full p-4 lg:p-8 grid grid-cols-1 lg:grid-cols-12 gap-6 lg:gap-8">

        {/* Left Column: Question Area */}
        <div className="lg:col-span-9 flex flex-col gap-6">
            <div className="bg-white dark:bg-[#1e293b] rounded-2xl shadow-sm border border-slate-200 dark:border-slate-700 p-6 lg:p-8 flex-1">
                {/* Question Meta */}
                <div className="flex items-center gap-3 mb-6">
                    <span className="text-xs font-bold text-primary bg-primary/10 px-2 py-1 rounded uppercase tracking-wider">Question {currentQuestionIndex + 1}</span>
                    <span className="text-xs font-semibold text-slate-400 dark:text-slate-500">•</span>
                    <span className="text-xs font-semibold text-slate-500 dark:text-slate-400">{currentQuestion.type}</span>
                    <span className="text-xs font-semibold text-slate-400 dark:text-slate-500">•</span>
                    <span className="text-xs font-semibold text-slate-500 dark:text-slate-400">{currentQuestion.points} Points</span>
                </div>

                {/* Question Text */}
                <h2 className="text-xl lg:text-2xl font-bold text-slate-900 dark:text-white leading-relaxed mb-8">
                    {currentQuestion.text}
                </h2>

                {/* Options */}
                <div className="space-y-4 mb-8">
                    {currentQuestion.options.map((opt) => {
                        const isSelected = answers[currentQuestion.id] === opt.id;
                        return (
                            <label 
                                key={opt.id} 
                                className={`group flex items-start gap-4 p-5 rounded-xl border-2 cursor-pointer transition-all ${isSelected ? 'border-primary bg-blue-50/50 dark:bg-blue-900/10' : 'border-slate-200 dark:border-slate-700 bg-white dark:bg-[#1e293b] hover:border-slate-300 dark:hover:border-slate-600'}`}
                            >
                                <div className="mt-0.5 shrink-0">
                                    <div className={`size-5 rounded-full border-2 flex items-center justify-center transition-colors ${isSelected ? 'border-primary' : 'border-slate-300 dark:border-slate-600 group-hover:border-slate-400'}`}>
                                        {isSelected && <div className="size-2.5 rounded-full bg-primary"></div>}
                                    </div>
                                    <input 
                                        type="radio" 
                                        name={`q-${currentQuestion.id}`} 
                                        className="hidden" 
                                        checked={isSelected}
                                        onChange={() => handleOptionSelect(opt.id)}
                                    />
                                </div>
                                <div>
                                    <p className={`text-base font-bold transition-colors ${isSelected ? 'text-primary' : 'text-slate-800 dark:text-slate-200'}`}>{opt.text}</p>
                                    {opt.subText && <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">{opt.subText}</p>}
                                </div>
                            </label>
                        )
                    })}
                </div>

                {/* Action Buttons */}
                <div className="flex items-center justify-between pt-6 border-t border-slate-100 dark:border-slate-700">
                    <button 
                        onClick={() => setCurrentQuestionIndex(Math.max(0, currentQuestionIndex - 1))}
                        disabled={isFirstQuestion}
                        className={`flex items-center gap-2 px-5 py-2.5 rounded-lg font-bold text-sm transition-colors ${isFirstQuestion ? 'text-slate-300 cursor-not-allowed' : 'text-slate-600 hover:bg-slate-50 hover:text-slate-900 dark:text-slate-400 dark:hover:bg-slate-800'}`}
                    >
                        <Icon name="arrow_back" className="text-sm" /> Previous
                    </button>

                    <button 
                        onClick={toggleFlag}
                        className={`flex items-center gap-2 px-5 py-2.5 rounded-lg font-bold text-sm transition-colors ${flagged.has(currentQuestion.id) ? 'bg-amber-50 text-amber-600 border border-amber-200' : 'text-slate-500 hover:text-amber-600 hover:bg-amber-50 border border-transparent'}`}
                    >
                        <Icon name="flag" className={`text-sm ${flagged.has(currentQuestion.id) ? 'fill-1' : ''}`} /> 
                        {flagged.has(currentQuestion.id) ? 'Flagged' : 'Flag for Review'}
                    </button>

                    <button 
                        onClick={() => setCurrentQuestionIndex(Math.min(totalQuestions - 1, currentQuestionIndex + 1))}
                        disabled={isLastQuestion}
                        className={`flex items-center gap-2 px-6 py-2.5 rounded-lg font-bold text-sm transition-all shadow-lg shadow-primary/20 ${isLastQuestion ? 'bg-slate-100 text-slate-400 cursor-not-allowed shadow-none' : 'bg-primary text-white hover:bg-primary/90'}`}
                    >
                        Next Question <Icon name="arrow_forward" className="text-sm" />
                    </button>
                </div>
            </div>

            <div className="bg-blue-50 dark:bg-blue-900/10 border border-blue-100 dark:border-blue-900/30 rounded-xl p-4 flex gap-3 text-blue-700 dark:text-blue-300">
                <Icon name="info" className="shrink-0" />
                <p className="text-xs leading-relaxed">Review your answer carefully. Shuffled options might appear differently than in your study materials.</p>
            </div>
        </div>

        {/* Right Column: Sidebar */}
