interface TeacherQuizResultsProps {
  onNavigate: (view: View) => void;
}

interface StudentResult {
  rank: number;
  name: string;
  id: string;
  time: string;
  score: string;
  grade: string;
  status: string;
  statusColor?: string;
  img: string;
  feedback: string;
}

const MOCK_DATA: StudentResult[] = [
  { rank: 1, name: 'Alice Freeman', id: 'STU-2023-902', time: '28m 12s', score: '98%', grade: 'A+', status: 'Graded', img: 'https://picsum.photos/seed/alice/100', feedback: 'Outstanding performance!' },
  { rank: 2, name: 'Ethan Hunt', id: 'STU-2023-441', time: '30m 45s', score: '95%', grade: 'A', status: 'Graded', img: 'https://picsum.photos/seed/ethan/100', feedback: 'Great analysis in section 2.' },
  { rank: 3, name: 'Charlie Lee', id: 'STU-2023-112', time: '42m 00s', score: '88%', grade: 'B+', status: 'Graded', img: 'https://picsum.photos/seed/charlie/100', feedback: 'Good work, watch the time.' },
  { rank: 4, name: 'Diana Evans', id: 'STU-2023-332', time: '35m 20s', score: '85%', grade: 'B', status: 'Graded', img: 'https://picsum.photos/seed/diana/100', feedback: 'Review cellular respiration.' },
  { rank: 5, name: 'Bob Thomas', id: 'STU-2023-881', time: '12m (Active)', score: '45%*', grade: '--', status: 'In Progress', statusColor: 'bg-blue-100 text-blue-700', img: 'https://picsum.photos/seed/bob/100', feedback: '' },
];

type SortKey = 'rank' | 'score' | 'time';

export const TeacherQuizResults: React.FC<TeacherQuizResultsProps> = ({ onNavigate }) => {
  const [students, setStudents] = useState<StudentResult[]>(MOCK_DATA);
  const [sortConfig, setSortConfig] = useState<{ key: SortKey; direction: 'asc' | 'desc' }>({ key: 'rank', direction: 'asc' });

  const stats = useMemo(() => {
    const completed = students.filter(s => s.status === 'Graded');
    const totalClassSize = 30; // Mock total class size

    const scores = completed.map(s => parseInt(s.score.replace(/[^0-9]/g, '')) || 0);
    const avgScore = scores.length ? Math.round(scores.reduce((a, b) => a + b, 0) / scores.length) : 0;
    const maxScore = scores.length ? Math.max(...scores) : 0;

    const times = completed.map(s => {
        const m = s.time.match(/(\d+)m/);
        return m ? parseInt(m[1]) : 0;
    });
    const avgTime = times.length ? Math.round(times.reduce((a, b) => a + b, 0) / times.length) : 0;

    const grades = {
        'A': completed.filter(s => s.grade.startsWith('A')).length,
        'B': completed.filter(s => s.grade.startsWith('B')).length,
        'C': completed.filter(s => s.grade.startsWith('C')).length,
        'D': completed.filter(s => s.grade.startsWith('D')).length,
        'F': completed.filter(s => s.grade.startsWith('F') || s.grade === 'F').length,
    };

    return { 
        completedCount: completed.length, 
        totalClassSize, 
        avgScore, 
        avgTime, 
        maxScore, 
        grades 
    };
  }, [students]);

  const handleSort = (key: SortKey) => {
    setSortConfig(current => ({
      key,
      direction: current.key === key && current.direction === 'asc' ? 'desc' : 'asc',
    }));
  };

  const sortedStudents = useMemo(() => {
    const sorted = [...students];
    sorted.sort((a, b) => {
      let aValue: number = 0;
      let bValue: number = 0;

      switch (sortConfig.key) {
        case 'rank':
          aValue = a.rank;
          bValue = b.rank;
          break;
        case 'score':
          // Convert '98%' to 98, '--' to -1, '45%*' to 45
          const parseScore = (s: string) => {
            if (s === '--') return -1;
            return parseInt(s.replace(/[^0-9]/g, ''));
          };
          aValue = parseScore(a.score);
          bValue = parseScore(b.score);
          break;
        case 'time':
          // Convert '28m 12s' to seconds. '--' is infinite (last)
          const parseTime = (t: string) => {
            if (t === '--') return 999999;
            const parts = t.match(/(\d+)m\s*(\d+)s/);
            if (parts) return parseInt(parts[1]) * 60 + parseInt(parts[2]);
            return 0;
          };
          aValue = parseTime(a.time);
          bValue = parseTime(b.time);
          break;
      }

      if (aValue < bValue) return sortConfig.direction === 'asc' ? -1 : 1;
      if (aValue > bValue) return sortConfig.direction === 'asc' ? 1 : -1;
      return 0;
    });
    return sorted;
