           <p className="text-xs text-slate-500">View real-time scores and student submissions.</p>
        </div>
        <div className="flex gap-3">
             <button className="flex items-center gap-2 px-3 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm font-bold text-slate-600 hover:bg-slate-50">
               <Icon name="refresh" /> Refresh
            </button>
            <button className="flex items-center gap-2 px-3 py-2 bg-primary text-white rounded-lg text-sm font-bold hover:bg-primary/90 shadow-lg shadow-primary/20">
               <Icon name="download" /> Export CSV
            </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-6 mb-8 shrink-0">
          <div className="bg-white dark:bg-slate-800 p-4 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm flex items-center gap-4">
