const MOCK_DATA: StudentResult[] = [
  { rank: 1, name: 'Alice Freeman', id: 'STU-2023-902', time: '28m 12s', score: '98%', grade: 'A+', status: 'Graded', img: 'https://picsum.photos/seed/alice/100', feedback: 'Outstanding performance!' },
  { rank: 2, name: 'Ethan Hunt', id: 'STU-2023-441', time: '30m 45s', score: '95%', grade: 'A', status: 'Graded', img: 'https://picsum.photos/seed/ethan/100', feedback: 'Great analysis in section 2.' },
  { rank: 3, name: 'Charlie Lee', id: 'STU-2023-112', time: '42m 00s', score: '88%', grade: 'B+', status: 'Graded', img: 'https://picsum.photos/seed/charlie/100', feedback: 'Good work, watch the time.' },
  { rank: 4, name: 'Diana Evans', id: 'STU-2023-332', time: '35m 20s', score: '85%', grade: 'B', status: 'Graded', img: 'https://picsum.photos/seed/diana/100', feedback: 'Review cellular respiration.' },
  { rank: 5, name: 'Bob Thomas', id: 'STU-2023-881', time: '12m (Active)', score: '45%*', grade: '--', status: 'In Progress', statusColor: 'bg-blue-100 text-blue-700', img: 'https://picsum.photos/seed/bob/100', feedback: '' },
];

type SortKey = 'rank' | 'score' | 'time';

export const TeacherQuizResults: React.FC<TeacherQuizResultsProps> = ({ onNavigate }) => {
  const [students, setStudents] = useState<StudentResult[]>(MOCK_DATA);
  const [sortConfig, setSortConfig] = useState<{ key: SortKey; direction: 'asc' | 'desc' }>({ key: 'rank', direction: 'asc' });

  const stats = useMemo(() => {
    const completed = students.filter(s => s.status === 'Graded');
    const totalClassSize = 30; // Mock total class size

    const scores = completed.map(s => parseInt(s.score.replace(/[^0-9]/g, '')) || 0);
    const avgScore = scores.length ? Math.round(scores.reduce((a, b) => a + b, 0) / scores.length) : 0;
    const maxScore = scores.length ? Math.max(...scores) : 0;

    const times = completed.map(s => {
        const m = s.time.match(/(\d+)m/);
        return m ? parseInt(m[1]) : 0;
    });
    const avgTime = times.length ? Math.round(times.reduce((a, b) => a + b, 0) / times.length) : 0;

    const grades = {
        'A': completed.filter(s => s.grade.startsWith('A')).length,
        'B': completed.filter(s => s.grade.startsWith('B')).length,
        'C': completed.filter(s => s.grade.startsWith('C')).length,
        'D': completed.filter(s => s.grade.startsWith('D')).length,
        'F': completed.filter(s => s.grade.startsWith('F') || s.grade === 'F').length,
    };

    return { 
        completedCount: completed.length, 
        totalClassSize, 
        avgScore, 
        avgTime, 
        maxScore, 
        grades 
    };
  }, [students]);

  const handleSort = (key: SortKey) => {
    setSortConfig(current => ({
      key,
      direction: current.key === key && current.direction === 'asc' ? 'desc' : 'asc',
    }));
  };

  const sortedStudents = useMemo(() => {
    const sorted = [...students];
    sorted.sort((a, b) => {
      let aValue: number = 0;
      let bValue: number = 0;

      switch (sortConfig.key) {
        case 'rank':
          aValue = a.rank;
          bValue = b.rank;
          break;
        case 'score':
          // Convert '98%' to 98, '--' to -1, '45%*' to 45
          const parseScore = (s: string) => {
            if (s === '--') return -1;
            return parseInt(s.replace(/[^0-9]/g, ''));
          };
          aValue = parseScore(a.score);
          bValue = parseScore(b.score);
          break;
        case 'time':
          // Convert '28m 12s' to seconds. '--' is infinite (last)
          const parseTime = (t: string) => {
            if (t === '--') return 999999;
            const parts = t.match(/(\d+)m\s*(\d+)s/);
            if (parts) return parseInt(parts[1]) * 60 + parseInt(parts[2]);
            return 0;
          };
          aValue = parseTime(a.time);
          bValue = parseTime(b.time);
          break;
      }

      if (aValue < bValue) return sortConfig.direction === 'asc' ? -1 : 1;
      if (aValue > bValue) return sortConfig.direction === 'asc' ? 1 : -1;
      return 0;
    });
    return sorted;
  }, [students, sortConfig]);

  const getSortIcon = (key: SortKey) => {
    if (sortConfig.key !== key) return <Icon name="unfold_more" className="text-slate-300 text-xs" />;
    return <Icon name={sortConfig.direction === 'asc' ? 'expand_less' : 'expand_more'} className="text-primary text-xs" />;
  };

  return (
    <div className="p-6 lg:p-8 max-w-[1400px] mx-auto h-full flex flex-col">
      <div className="flex justify-between items-center mb-6 shrink-0">
        <div>
           <button 
            onClick={() => onNavigate(View.TEACHER_QUIZ_SHARE)}
            className="flex items-center gap-1 text-sm font-bold text-primary hover:underline mb-2"
           >
            <Icon name="arrow_back" className="text-sm" /> Back to Sharing
           </button>
           <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Quiz Results: Biology 101 Midterm</h1>

           <div className="flex flex-wrap items-center gap-x-6 gap-y-2 mt-2 text-sm text-slate-500">
                <div className="flex items-center gap-1.5">
                    <Icon name="event" className="text-slate-400 text-[18px]" />
                    <span>Administered: <span className="font-semibold text-slate-700 dark:text-slate-300">Oct 24, 2023</span></span>
                </div>
                <div className="hidden sm:block w-px h-4 bg-slate-300 dark:bg-slate-700"></div>
                <div className="flex items-center gap-1.5">
                    <Icon name="military_tech" className="text-slate-400 text-[18px]" />
                    <span>Total Points: <span className="font-semibold text-slate-700 dark:text-slate-300">100</span></span>
                </div>
                <div className="hidden sm:block w-px h-4 bg-slate-300 dark:bg-slate-700"></div>
                <div className="flex items-center gap-1.5">
                    <Icon name="schedule" className="text-slate-400 text-[18px]" />
                    <span>Time Limit: <span className="font-semibold text-slate-700 dark:text-slate-300">45 mins</span></span>
                </div>
           </div>
        </div>
        <div className="flex gap-3">
             <button className="flex items-center gap-2 px-3 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm font-bold text-slate-600 hover:bg-slate-50">
               <Icon name="refresh" /> Refresh
            </button>
            <button className="flex items-center gap-2 px-3 py-2 bg-primary text-white rounded-lg text-sm font-bold hover:bg-primary/90 shadow-lg shadow-primary/20">
               <Icon name="download" /> Export CSV
            </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-6 mb-8 shrink-0">
          <div className="bg-white dark:bg-slate-800 p-4 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm flex items-center gap-4">
              <div className="size-12 rounded-lg bg-blue-50 dark:bg-blue-900/20 text-primary flex items-center justify-center font-bold text-xl">
                 <Icon name="groups" />
              </div>
              <div>
                  <p className="text-xs font-bold uppercase text-slate-500">Participants</p>
                  <p className="text-2xl font-black text-slate-900 dark:text-white">{stats.completedCount}/{stats.totalClassSize}</p>
              </div>
          </div>
          <div className="bg-white dark:bg-slate-800 p-4 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm flex items-center gap-4">
              <div className="size-12 rounded-lg bg-green-50 dark:bg-green-900/20 text-green-600 flex items-center justify-center font-bold text-xl">
                 <Icon name="analytics" />
              </div>
              <div>
                  <p className="text-xs font-bold uppercase text-slate-500">Avg. Score</p>
                  <p className="text-2xl font-black text-slate-900 dark:text-white">{stats.avgScore}%</p>
              </div>
          </div>
           <div className="bg-white dark:bg-slate-800 p-4 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm flex items-center gap-4">
              <div className="size-12 rounded-lg bg-orange-50 dark:bg-orange-900/20 text-orange-600 flex items-center justify-center font-bold text-xl">
                 <Icon name="timer" />
              </div>
              <div>
                  <p className="text-xs font-bold uppercase text-slate-500">Avg. Time</p>
                  <p className="text-2xl font-black text-slate-900 dark:text-white">{stats.avgTime}m</p>
              </div>
          </div>
          <div className="bg-white dark:bg-slate-800 p-4 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm flex items-center gap-4">
              <div className="size-12 rounded-lg bg-purple-50 dark:bg-purple-900/20 text-purple-600 flex items-center justify-center font-bold text-xl">
                 <Icon name="emoji_events" />
              </div>
              <div>
                  <p className="text-xs font-bold uppercase text-slate-500">Top Score</p>
                  <p className="text-2xl font-black text-slate-900 dark:text-white">{stats.maxScore}%</p>
              </div>
          </div>
      </div>

      {/* Analytics Section */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-8 shrink-0">
          <div className="bg-white dark:bg-slate-800 p-6 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm">
             <h3 className="font-bold text-slate-900 dark:text-white mb-6 flex items-center gap-2">
                 <Icon name="bar_chart" className="text-primary" /> Grade Distribution
             </h3>
             <div className="space-y-4">
                 {[
                     { label: 'A Range (90-100%)', count: stats.grades['A'], color: 'bg-green-500' },
                     { label: 'B Range (80-89%)', count: stats.grades['B'], color: 'bg-blue-500' },
                     { label: 'C Range (70-79%)', count: stats.grades['C'], color: 'bg-yellow-500' },
                     { label: 'D Range (60-69%)', count: stats.grades['D'], color: 'bg-orange-500' },
                     { label: 'Needs Improvement (<60%)', count: stats.grades['F'], color: 'bg-red-500' },
                 ].map((grade, i) => (
                     <div key={i} className="flex items-center gap-4">
                         <div className="w-40 text-xs font-bold text-slate-500">{grade.label}</div>
                         <div className="flex-1 h-3 bg-slate-100 dark:bg-slate-700 rounded-full overflow-hidden">
                             <div 
                                className={`h-full rounded-full transition-all duration-500 ${grade.color}`} 
                                style={{ width: `${stats.completedCount > 0 ? (grade.count / stats.completedCount) * 100 : 0}%` }}
                             ></div>
                         </div>
                         <div className="w-8 text-right text-xs font-bold text-slate-900 dark:text-white">{grade.count}</div>
                     </div>
                 ))}
             </div>
          </div>

          <div className="bg-white dark:bg-slate-800 p-6 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm flex flex-col">
              <h3 className="font-bold text-slate-900 dark:text-white mb-6 flex items-center gap-2">
                  <Icon name="pie_chart" className="text-purple-600" /> Completion Overview
              </h3>
              <div className="flex flex-1 items-center justify-around">
                  <div className="relative size-32">
                      <svg className="size-full -rotate-90" viewBox="0 0 36 36">
                          <path d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831" fill="none" stroke="#e2e8f0" strokeWidth="4" className="dark:stroke-slate-700" />
                          <path 
                            d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831" 
                            fill="none" 
                            stroke="#3b82f6" 
                            strokeWidth="4" 
                            strokeDasharray={`${(stats.completedCount / stats.totalClassSize) * 100}, 100`} 
                            className="transition-all duration-1000 ease-out"
                          />
                      </svg>
                      <div className="absolute inset-0 flex flex-col items-center justify-center">
                          <span className="text-2xl font-black text-slate-900 dark:text-white">{Math.round((stats.completedCount / stats.totalClassSize) * 100)}%</span>
                          <span className="text-[10px] font-bold text-slate-500 uppercase">Completed</span>
                      </div>
                  </div>
                  <div className="space-y-4">
                      <div className="flex items-center gap-3">
                          <span className="size-3 rounded-full bg-blue-500"></span>
                          <div>
                              <p className="text-xs font-bold text-slate-500 uppercase">Submitted</p>
                              <p className="text-lg font-bold text-slate-900 dark:text-white">{stats.completedCount}</p>
                          </div>
                      </div>
                      <div className="flex items-center gap-3">
                          <span className="size-3 rounded-full bg-slate-200 dark:bg-slate-700"></span>
                          <div>
                              <p className="text-xs font-bold text-slate-500 uppercase">Pending</p>
                              <p className="text-lg font-bold text-slate-900 dark:text-white">{stats.totalClassSize - stats.completedCount}</p>
                          </div>
                      </div>
                  </div>
              </div>
          </div>
      </div>

      <div className="bg-white dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 shadow-sm overflow-hidden flex-1 flex flex-col">
          <div className="p-4 bg-slate-50 dark:bg-slate-900/50 border-b border-slate-200 dark:border-slate-700 flex justify-between items-center">
              <h3 className="font-bold text-slate-800 dark:text-white">Student Leaderboard</h3>
              <div className="relative">
                  <Icon name="search" className="absolute left-3 top-2.5 text-slate-400 text-sm" />
                  <input type="text" placeholder="Filter by name or ID..." className="pl-9 pr-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-sm w-64" />
              </div>
          </div>
          <div className="flex-1 overflow-auto">
              <table className="w-full text-left">
                  <thead className="bg-slate-50 dark:bg-slate-900/50 text-[10px] uppercase font-bold text-slate-500 sticky top-0 z-10">
                      <tr>
                          <th className="px-6 py-4 w-16 text-center cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors" onClick={() => handleSort('rank')}>
                             <div className="flex items-center justify-center gap-1">
                                Rank {getSortIcon('rank')}
                             </div>
                          </th>
                          <th className="px-6 py-4">Student Name</th>
                          <th className="px-6 py-4">Student ID</th>
                          <th className="px-6 py-4 cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors" onClick={() => handleSort('time')}>
                              <div className="flex items-center gap-1">
                                Time Taken {getSortIcon('time')}
                              </div>
                          </th>
                          <th className="px-6 py-4 cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors" onClick={() => handleSort('score')}>
                              <div className="flex items-center gap-1">
                                Score {getSortIcon('score')}
                              </div>
                          </th>
                          <th className="px-6 py-4 text-center">Grade</th>
                          <th className="px-6 py-4 w-1/4">Teacher Feedback</th>
                          <th className="px-6 py-4 text-center">Status</th>
                          <th className="px-6 py-4 text-right">Actions</th>
                      </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                      {sortedStudents.map((row, i) => (
                          <tr key={i} className="hover:bg-slate-50 dark:hover:bg-slate-700/30 transition-colors group">
                              <td className="px-6 py-4 text-center font-bold text-slate-400">
                                  {row.rank <= 3 ? <div className={`size-8 rounded-full flex items-center justify-center mx-auto text-white ${row.rank === 1 ? 'bg-yellow-400' : row.rank === 2 ? 'bg-slate-300' : 'bg-orange-300'}`}>{row.rank}</div> : `#${row.rank}`}
                              </td>
                              <td className="px-6 py-4">
                                  <div className="flex items-center gap-3">
                                      <div className="size-8 rounded-full bg-cover bg-center" style={{ backgroundImage: `url(${row.img})` }}></div>
                                      <span className="font-bold text-sm text-slate-900 dark:text-white">{row.name}</span>
                                  </div>
                              </td>
                              <td className="px-6 py-4 font-mono text-xs text-slate-500">{row.id}</td>
                              <td className="px-6 py-4 text-sm text-slate-600 dark:text-slate-300">{row.time}</td>
                              <td className="px-6 py-4 font-black text-slate-900 dark:text-white">
                                {row.status === 'In Progress' ? (
                                   <div className="flex flex-col">
                                       <span>{row.score.replace('*', '')}</span>
                                       <span className="text-[10px] font-medium text-slate-400 uppercase tracking-wider">Partial</span>
                                   </div>
                                ) : (
                                    row.score
                                )}
                              </td>
                              <td className="px-6 py-4 text-center">
                                  <span className={`inline-flex size-8 items-center justify-center rounded-lg text-sm font-bold ${
                                      row.grade.startsWith('A') ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400' :
                                      row.grade.startsWith('B') ? 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400' :
                                      row.grade === '--' ? 'bg-slate-100 text-slate-500 dark:bg-slate-800' :
                                      'bg-orange-100 text-orange-700'
                                  }`}>
                                      {row.grade}
                                  </span>
                              </td>
                              <td className="px-6 py-4 text-xs text-slate-500 relative">
                                  {row.feedback ? (
                                      <span className="line-clamp-1">{row.feedback}</span>
                                  ) : (
                                      <span className="text-slate-300 italic">No feedback added</span>
                                  )}
                                  <button className="absolute right-2 top-1/2 -translate-y-1/2 opacity-0 group-hover:opacity-100 p-1 hover:bg-slate-200 dark:hover:bg-slate-700 rounded text-primary transition-all">
                                      <Icon name="edit" className="text-xs" />
                                  </button>
                              </td>
                              <td className="px-6 py-4 text-center">
                                  <span className={`inline-block px-2 py-1 rounded text-[10px] font-bold uppercase ${row.statusColor || 'bg-green-100 text-green-700'}`}>{row.status}</span>
                              </td>
                              <td className="px-6 py-4 text-right">
                                  <button className="text-xs font-bold text-primary hover:underline">View Answers</button>
                              </td>
                          </tr>
                      ))}
                  </tbody>
              </table>
          </div>
      </div>
    </div>
  );
};
